def query_with_kg(query, concept):
    """Query with knowledge graph enrichment."""
    # 1. KG node retrieval
    kg_nodes = kb.get_node(concept)  # May be None or empty

    # 2. Clinical co-occurrence data (always run this; it's the real signal)
    res = db.execute(sql_queries.CLINICAL_CO_OCCURRENCE.format(
        stage_term=concept.replace(' ', '_').lower(), 
        clinical_limit=150,
        concept_id=query.get('concept_id') or ''
    ))

    # If no KG nodes, just return the clinical co-occurrence data — don't time out on empty join
    if not kg_nodes:
        return dict(result=res.rows, query=query, status='clinical_only', note="No KBP node for this concept")
